-- ════════════════════════════════════════════════════════════════════
-- Paris : page de garde « Menu » (Bar à Huîtres au cœur de Paris · Voir le menu)
-- C'est l'image qui passe en premier dans l'export Instagram (Exporter › Instagram › Page de garde).
-- Touche le vrai site de Paris (drevici) et sa copie de test. Sans danger si relancé.
-- ════════════════════════════════════════════════════════════════════
update public.menu_data
set data = jsonb_set(data, '{pdfStyle}', coalesce(data->'pdfStyle', '{}'::jsonb) || jsonb_build_object('instaCover', 'data:image/webp;base64,'::text)),
    updated_at = now()
where client_slug in ('drevici', 'drevici-test');

-- Vérification : 2 lignes avec « page de garde = true »
select client_slug, (data->'pdfStyle'->>'instaCover') like 'data:image/webp%' as page_de_garde
from public.menu_data where client_slug in ('drevici', 'drevici-test');
